mapper.select:
select f.business_date as date, p.source_code as source, count(*) as total_lines, count(*) filter (where p.status = 'MATCHED' and g.method in ('EXACT', 'AMOUNT_DATE', 'MANY_TO_ONE')) as auto_matched, count(*) filter (where (p.status = 'MATCHED' and g.method in ('MANUAL', 'AI_CONFIRMED')) or p.status = 'DUPLICATE' or (p.status = 'EXCEPTION' and coalesce(x.closed, false))) as manual_matched, count(*) filter (where p.status in ('NEW', 'EXCEPTION') and not coalesce(x.closed, false)) as exceptions, coalesce(sum(p.amount), 0) as amount_in, coalesce(sum(p.fee), 0) as fee_total from payment_lines p join import_files f on f.id = p.file_id left join match_groups g on g.id = p.match_group_id left join lateral ( select bool_and(e.status in ('RESOLVED', 'WRITTEN_OFF')) as closed from exception_payments ep join recon_exceptions e on e.id = ep.exception_id where ep.payment_line_id = p.id and e.type <> 'FEE_DIFF' ) x on true where f.business_date between #{from} and #{to}
and p.source_code in #{s}
group by f.business_date, p.source_code order by f.business_date desc, p.source_code

select e.id, e.type, e.source_code, e.status, e.diff_amount, e.created_at, e.sla_due_at, e.assignee_id, e.version, (e.ai ->> 'confidence')::float8 as ai_confidence, o.code as order_code, o.customer_name, o.tracking_code, p.external_ref, p.description from recon_exceptions e left join lateral ( select oo.code, oo.customer_name, oo.tracking_code from exception_orders eo join oms.orders oo on oo.code = eo.order_code where eo.exception_id = e.id order by oo.code limit 1 ) o on true left join lateral ( select pp.external_ref, pp.description from exception_payments ep join payment_lines pp on pp.id = ep.payment_line_id where ep.exception_id = e.id order by ep.position limit 1 ) p on true
e.status in ('OPEN', 'IN_REVIEW') e.status = 'WRITE_OFF_PENDING' e.status in ('RESOLVED', 'WRITTEN_OFF')
and e.type in #{t}
and e.source_code in #{s}
and e.assignee_id is null and e.assignee_id = #{q.assignee}
and e.status = 'OPEN' and e.sla_due_at < #{q.now}
and (upper(e.id) like #{q.like()} or upper(o.code) like #{q.like()} or upper(o.customer_name) like #{q.like()} or upper(o.tracking_code) like #{q.like()} or upper(p.external_ref) like #{q.like()} or upper(p.description) like #{q.like()})
order by case when e.status = 'OPEN' then 0 else 1 end, e.sla_due_at asc, e.created_at desc, e.id desc limit #{q.limit}

select coalesce(sum(abs(diff_amount)), 0) as amount, count(*) as count
from recon_exceptions
where type = 'FEE_DIFF' and created_at >= #{since}
